  "Only selected": { "es": "Solo las seleccionadas", "pt-BR": "Só as selecionadas" },
  "1 selected display is not connected right now — the choice is kept for when it is back.": { "es": "Una pantalla seleccionada no está conectada ahora mismo — la elección se guarda para cuando vuelva.", "pt-BR": "Uma tela selecionada não está conectada agora — a escolha fica guardada para quando ela voltar." },
  "%lld selected displays are not connected right now — the choice is kept for when it is back.": { "es": "%lld pantallas seleccionadas no están conectadas ahora mismo — la elección se guarda para cuando vuelvan.", "pt-BR": "%lld telas selecionadas não estão conectadas agora — a escolha fica guardada para quando elas voltarem." },
  "Mochi rests at the top of every display you allow. She opens, and shows notifications, on the one your pointer is on.": { "es": "Mochi descansa en la parte de arriba de cada pantalla que permitas. Se abre, y muestra las notificaciones, en aquella donde esté tu puntero.", "pt-BR": "O Mochi descansa no alto de cada tela que você permitir. Ele abre, e mostra as notificações, naquela onde está o seu ponteiro." },
  "Last message": { "es": "Último mensaje", "pt-BR": "Última mensagem" },
