  "Pill switched off — nothing connects to it.": { "es": "Píldora apagada — no se conecta nada a ella.", "pt-BR": "Pastilha desligada — nada se conecta a ela." },
  "Fill in the address, the login and the password.": { "es": "Rellena la dirección, el usuario y la contraseña.", "pt-BR": "Preencha o endereço, o usuário e a senha." },
  "Saved. Notchy signs in shortly, or press Sign in.": { "es": "Guardado. Notchy iniciará sesión en breve, o pulsa Iniciar sesión.", "pt-BR": "Salvo. O Notchy entra daqui a pouco, ou aperte Entrar." },
