  "Tap the glass whenever you drink. At your own pace.": { "es": "Toca el vaso cada vez que bebas. A tu ritmo.", "pt-BR": "Toque no copo sempre que beber. No seu ritmo." },
  "Your glass is waiting. Tap it when you drink.": { "es": "Tu vaso te espera. Tócalo cuando bebas.", "pt-BR": "Seu copo está esperando. Toque nele quando beber." },
  "Today's goal reached. Reminders rest until tomorrow.": { "es": "Meta de hoy alcanzada. Los recordatorios descansan hasta mañana.", "pt-BR": "Meta de hoje alcançada. Os lembretes descansam até amanhã." },
  "Today's goal reached: %lld days in a row. Reminders rest until tomorrow.": { "es": "Meta de hoy alcanzada: %lld días seguidos. Los recordatorios descansan hasta mañana.", "pt-BR": "Meta de hoje alcançada: %lld dias seguidos. Os lembretes descansam até amanhã." },
  "Today's goal is already reached. From here on, follow your thirst.": { "es": "La meta de hoy ya está alcanzada. De aquí en adelante, sigue tu sed.", "pt-BR": "Meta de hoje já alcançada. Daqui em diante, siga a sua sede." },
  "Reminders paused. You can still log whenever you like.": { "es": "Recordatorios en pausa. Puedes registrar cuando quieras.", "pt-BR": "Lembretes pausados. Você ainda pode registrar quando quiser." },
  "Up to %@ today. Reminders stop before you get there.": { "es": "Hasta %@ hoy. Los recordatorios paran antes de que llegues.", "pt-BR": "Até %@ hoje. Os lembretes param antes de chegar lá." },
