  "Mochi greets you by this name when Notchy starts, and uses it in the chat.": { "es": "Mochi te saluda con este nombre cuando Notchy se abre, y lo usa en el chat.", "pt-BR": "O Mochi te cumprimenta por este nome quando o Notchy abre, e usa esse nome no chat." },
  "Show the welcome again…": { "es": "Ver la bienvenida otra vez…", "pt-BR": "Rever as boas-vindas…" },
  "Welcome to Notchy": { "es": "Te damos la bienvenida a Notchy", "pt-BR": "Boas-vindas ao Notchy" },
